import { runMany, hex } from './lib.mjs';

const F = '一';
function mk(cps) { return F + cps.map(c => String.fromCodePoint(c) + F).join(''); }

// sanity: known cases
const tests = [
  ['a', 0x61], ['underscore', 0x5f], ['ZWNJ', 0x200c], ['ZWJ', 0x200d],
  ['middle dot', 0x00b7], ['greek keraia', 0x0375], ['heb geresh', 0x05f3],
  ['katakana midpt', 0x30fb], ['arabic-indic 0', 0x0660], ['ext arabic-indic 0', 0x06f0],
  ['unassigned-ish', 0x0378], ['CJK ExtI', 0x2ebf0], ['U+2FFC', 0x2ffc], ['U+31EF', 0x31ef],
];
const domains = tests.map(t => mk([t[1]]));
const res = await runMany(domains);
res.forEach((r, i) => {
  console.log(tests[i][0], hex(tests[i][1]), '| rc=' + r.rc, '| L1:', JSON.stringify(r.lines[0]));
});

// chunk test
const chunk = [];
for (let c = 0x61; c <= 0x7a; c++) chunk.push(c);
chunk.push(0x5f);
for (let c = 0x30; c <= 0x39; c++) chunk.push(c);
const r2 = await runMany([mk(chunk)]);
console.log('chunk:', JSON.stringify(r2[0].lines[0]), 'rc=', r2[0].rc);
